<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
function rdb(){static $p;if($p)return $p;$p=new PDO('mysql:host='.(getenv('DB_HOST')?:'127.0.0.1').';port='.(getenv('DB_PORT')?:'3306').';dbname='.(getenv('DB_NAME')?:'datasell').';charset=utf8mb4',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
if(empty($_SESSION['uid'])){header('Location:/?page=login');exit;}$id=(int)($_GET['id']??0);$q=rdb()->prepare('SELECT t.*,u.fullname,u.email FROM transactions t JOIN users u ON u.id=t.user_id WHERE t.id=? AND t.user_id=?');$q->execute([$id,(int)$_SESSION['uid']]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Receipt not found.');}$d=json_decode($t['details']??'{}',true)?:[];function e($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IHLink Receipt</title><style>body{margin:0;background:#f5f5ef;font:14px Arial;color:#2f3020}.r{max-width:620px;margin:35px auto;background:#fff;border-radius:22px;padding:28px;box-shadow:0 16px 50px #0001}.brand{font-size:22px;font-weight:900}.ok{display:inline-block;padding:7px 11px;border-radius:20px;background:#eef3e8;color:#596235;font-weight:800}.row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #eee}.row span{color:#777}.amount{font-size:34px;font-weight:900;margin:20px 0}.actions{display:flex;gap:10px;margin-top:24px}.actions a,.actions button{border:0;border-radius:11px;padding:12px 16px;text-decoration:none;font-weight:800;cursor:pointer}.primary{background:#d96846;color:#fff}.secondary{background:#eef0e8;color:#2f3020}@media print{body{background:#fff}.r{box-shadow:none;margin:0}.actions{display:none}}</style></head><body><main class="r"><div class="brand">IHLink Datasub</div><p>Transaction Receipt</p><div class="amount">₦<?=number_format((float)$t['amount'],2)?></div><span class="ok"><?=e(ucfirst($t['status']))?></span><div class="row"><span>Reference</span><b><?=e($t['reference'])?></b></div><div class="row"><span>Service</span><b><?=e(ucfirst($t['type']))?></b></div><div class="row"><span>Provider</span><b><?=e($d['provider']??'—')?></b></div><div class="row"><span>Plan</span><b><?=e($d['plan']??'—')?></b></div><div class="row"><span>Recipient</span><b><?=e($d['recipient']??'—')?></b></div><div class="row"><span>Date</span><b><?=e($t['created_at'])?></b></div><div class="row"><span>Customer</span><b><?=e($t['fullname'])?></b></div><div class="actions"><button class="primary" onclick="window.print()">Print / Save PDF</button><a class="secondary" href="/?page=transactions">Transactions</a><?php if(!empty($d['plan_code'])):?><a class="secondary" href="/?page=<?=e($t['type'])?>">Buy Again</a><?php endif;?></div></main></body></html>